head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setDisabled(!gridView1.getDisabled());
};
scwin.trigger2_onclick = function(e) {
    gridView1.setCellDisabled(0, "col1", !gridView1.getCellDisabled(0, "col1"));
};
scwin.aa = function(row, col) {
    //console.log("clickeD=" + row + "," + col);
    console.log(gridView1.getCheckedIndex(col));
}
scwin.bb = function(headerId) {
    // console.log("headerclicked=" + headerId);
    console.log(gridView1.getCheckedIndex("col1"));
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 그리드뷰의 부분체크가 되어있는 샘플파일을 실행 후 F12누르고 consol창에서 입력한다.gridView1.getHeaderValue("column5");
    //1. Execute the sample file with the partial check in the grid view, press F12 and enter it in the consol window.gridView1.getHeaderValue ("column5");
    //Verify step 1. The result is false.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1').getHeaderValue('column5')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그리드뷰를 전체체크로 변경 후 consol창에서다시 입력한다.gridView1.getHeaderValue('column5');
    //2. Change grid view to full check and re-enter in consol window.gridView1.getHeaderValue ('column5');
    //Verify step 2. The input result is shown as true.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_0').childNodes[0].click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_3_0').childNodes[0].click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_5_0').childNodes[0].click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_7_0').childNodes[0].click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1').setTopRowIndex(6)");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_5_0').childNodes[0].click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_7_0').childNodes[0].click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1').getHeaderValue('column5')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData(["1", 1, 2, "0", 3, 4, "1", 5, 6, "0", 7, 8, "1", 1, 2, "0", 3, 4, "1", 5, 6, "0", 7, 8, "1", 1, 2, "0", 3, 4, "1", 5, 6, "0", 7, 8]);
    //Function 
